from collections.abc import Mapping
from dataclasses import dataclass

from pr_radar.contracts import (
    AiSignalCalibrationReason,
    AiSignalFinding,
    AiSignalStrength,
    AiSignalType,
    CommitMetadata,
    DecisionSource,
    EvidenceReference,
    FindingStatus,
    PrEvidencePack,
    RedactedExcerpt,
)
from pr_radar.privacy.redaction import redact_excerpt


_AGENT_BRANCH_PREFIXES = ("agent", "cursor", "copilot", "devin")
_PR_SIGNATURES = (
    "generated with claude",
    "generated with claude code",
    "generated with codex",
    "generated with cursor",
    "generated by claude",
    "generated by codex",
    "generated by cursor",
)
_REPO_MARKER_FILES = ("AGENTS.md", "CLAUDE.md")


@dataclass(frozen=True)
class _AiSignalCalibration:
    status: FindingStatus
    score: int
    confidence: float
    decision_source: DecisionSource
    tags: tuple[str, ...]
    reason: AiSignalCalibrationReason


_DETERMINISTIC_CALIBRATION: Mapping[AiSignalType, _AiSignalCalibration] = {
    "bot_actor": _AiSignalCalibration(
        status="warning",
        score=90,
        confidence=0.9,
        decision_source="deterministic",
        tags=(),
        reason="bot_identity_strong_ai_assistance_signal",
    ),
    "branch_prefix": _AiSignalCalibration(
        status="warning",
        score=70,
        confidence=0.7,
        decision_source="deterministic",
        tags=(),
        reason="agent_branch_prefix_medium_ai_assistance_signal",
    ),
    "pr_signature": _AiSignalCalibration(
        status="warning",
        score=95,
        confidence=0.95,
        decision_source="deterministic",
        tags=(),
        reason="explicit_pr_body_signature_strong_ai_assistance_signal",
    ),
    "repo_marker": _AiSignalCalibration(
        status="info",
        score=35,
        confidence=0.35,
        decision_source="deterministic",
        tags=("low confidence",),
        reason="repo_marker_weak_project_level_signal",
    ),
}


def detect_ai_signals(
    evidence_pack: PrEvidencePack,
) -> tuple[AiSignalFinding, ...]:
    findings: list[AiSignalFinding] = []
    findings.extend(_bot_actor_findings(evidence_pack.commits))
    branch_finding = _branch_prefix_finding(evidence_pack)
    if branch_finding is not None:
        findings.append(branch_finding)
    signature_finding = _pr_signature_finding(evidence_pack)
    if signature_finding is not None:
        findings.append(signature_finding)
    findings.extend(_repo_marker_findings(evidence_pack))
    return tuple(findings)


def _bot_actor_findings(
    commits: tuple[CommitMetadata, ...],
) -> tuple[AiSignalFinding, ...]:
    findings: list[AiSignalFinding] = []
    for commit in commits:
        actor_logins = (commit.author_login, commit.committer_login)
        bot_logins = tuple(login for login in actor_logins if _is_bot_login(login))
        if not bot_logins:
            continue

        evidence_ref = EvidenceReference(kind="commit", ref=f"commit:{commit.sha}")
        findings.append(
            _calibrated_finding(
                signal_type="bot_actor",
                strength="strong",
                title="Commit actor uses a bot identity",
                evidence_refs=(evidence_ref,),
            ),
        )
    return tuple(findings)


def _branch_prefix_finding(
    evidence_pack: PrEvidencePack,
) -> AiSignalFinding | None:
    head_ref = evidence_pack.pr_metadata.head_ref
    normalized_head_ref = head_ref.lower()
    if not any(
        normalized_head_ref.startswith(f"{prefix}/")
        for prefix in _AGENT_BRANCH_PREFIXES
    ):
        return None

    evidence_ref = EvidenceReference(kind="pr", ref=f"head_ref:{head_ref}")
    return _calibrated_finding(
        signal_type="branch_prefix",
        strength="medium",
        title="Pull request branch uses an agent-style prefix",
        evidence_refs=(evidence_ref,),
    )


def _pr_signature_finding(
    evidence_pack: PrEvidencePack,
) -> AiSignalFinding | None:
    body = evidence_pack.pr_metadata.body
    normalized_body = body.lower()
    if not any(signature in normalized_body for signature in _PR_SIGNATURES):
        return None

    evidence_ref = EvidenceReference(kind="pr", ref="body:signature")
    return _calibrated_finding(
        signal_type="pr_signature",
        strength="strong",
        title="Pull request body contains an AI-generation signature",
        evidence_refs=(evidence_ref,),
        redacted_excerpts=(
            redact_excerpt(evidence_ref=evidence_ref, text=body),
        ),
    )


def _repo_marker_findings(
    evidence_pack: PrEvidencePack,
) -> tuple[AiSignalFinding, ...]:
    findings: list[AiSignalFinding] = []
    for path in evidence_pack.raw_evidence.file_contents:
        if not _is_repo_marker_path(path):
            continue

        evidence_ref = EvidenceReference(kind="repo_file", ref=f"file:{path}")
        findings.append(
            _calibrated_finding(
                signal_type="repo_marker",
                strength="weak",
                title="Repository contains agent instruction markers",
                evidence_refs=(evidence_ref,),
            ),
        )
    return tuple(findings)


def _calibrated_finding(
    *,
    signal_type: AiSignalType,
    strength: AiSignalStrength,
    title: str,
    evidence_refs: tuple[EvidenceReference, ...],
    redacted_excerpts: tuple[RedactedExcerpt, ...] = (),
) -> AiSignalFinding:
    calibration = _DETERMINISTIC_CALIBRATION[signal_type]
    return AiSignalFinding(
        signal_type=signal_type,
        strength=strength,
        title=title,
        status=calibration.status,
        score=calibration.score,
        confidence=calibration.confidence,
        evidence_refs=evidence_refs,
        redacted_excerpts=redacted_excerpts,
        decision_source=calibration.decision_source,
        calibration_reason=calibration.reason,
        tags=calibration.tags,
    )


def _is_bot_login(login: str) -> bool:
    return login.lower().endswith("[bot]")


def _is_repo_marker_path(path: str) -> bool:
    normalized_path = path.strip("/")
    return (
        normalized_path.startswith(".agents/")
        or normalized_path in _REPO_MARKER_FILES
    )
